static inline uint32_t rotr(uint32_t x, int n){ return (x>>n)|(x<<(32-n)); }

static void sha256_block(uint32_t state[8], const uint8_t block[64]){
    __m128i mask = _mm_set_epi8(12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);
    __m128i w0 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+0)), mask);
    __m128i w1 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+16)), mask);
    __m128i w2 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+32)), mask);
    __m128i w3 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+48)), mask);

    uint32_t W[64];
    _mm_storeu_si128((__m128i*)(W+0), w0);
    _mm_storeu_si128((__m128i*)(W+4), w1);
    _mm_storeu_si128((__m128i*)(W+8), w2);
    _mm_storeu_si128((__m128i*)(W+12), w3);

    /* Vectorized schedule: produce 4 words per iteration.
       W[i] = W[i-16] + sig0(W[i-15]) + W[i-7] + sig1(W[i-2])
       For a 4-word group starting at i (i%4==0, i>=16):
         sig0 inputs are W[i-15 .. i-12] which are known.
         sig1 inputs are W[i-2 .. i+1]; W[i] and W[i+1] are being computed,
         so we compute the first 2 with partial dependence then the next 2.
       Standard SSE technique (from Intel / sphlib):
    */
    for (int i = 16; i < 64; i += 4) {
        /* We recompute from stored W using SSE on sliding windows. */
        __m128i v_m15 = _mm_loadu_si128((const __m128i*)(W + i - 15)); /* may be unaligned ok */
        __m128i v_m2  = _mm_loadu_si128((const __m128i*)(W + i - 2));
        __m128i v_m16 = _mm_loadu_si128((const __m128i*)(W + i - 16));
        __m128i v_m7  = _mm_loadu_si128((const __m128i*)(W + i - 7));

        /* sig0 */
        __m128i s0 = _mm_xor_si128(
            _mm_xor_si128(_mm_or_si128(_mm_srli_epi32(v_m15, 7), _mm_slli_epi32(v_m15, 25)),
                          _mm_or_si128(_mm_srli_epi32(v_m15, 18), _mm_slli_epi32(v_m15, 14))),
            _mm_srli_epi32(v_m15, 3));
        /* Problem: sig1(W[i-2]) for the 3rd and 4th lanes depends on W[i], W[i+1]
           which we haven't computed. So this direct approach is WRONG for lanes 2,3.
           We'll compute only lane 0-1 vectorially? Let's just do scalar for correctness first,
           then a correct vector schedule.
        */
        (void)s0; (void)v_m2; (void)v_m16; (void)v_m7;
        for (int j = 0; j < 4; j++) {
            uint32_t x = W[i+j-15];
            uint32_t y = W[i+j-2];
            uint32_t s0s = rotr(x,7)^rotr(x,18)^(x>>3);
            uint32_t s1s = rotr(y,17)^rotr(y,19)^(y>>10);
            W[i+j] = W[i+j-16] + s0s + W[i+j-7] + s1s;
        }
    }

    uint32_t a=state[0],b=state[1],c=state[2],d=state[3],e=state[4],f=state[5],g=state[6],h=state[7];
    /* unroll rounds a bit */
    for (int i = 0; i < 64; i++) {
        uint32_t S1 = rotr(e,6)^rotr(e,11)^rotr(e,25);
        uint32_t ch = (e & f) ^ ((~e) & g);
        uint32_t t1 = h + S1 + ch + K[i] + W[i];
        uint32_t S0 = rotr(a,2)^rotr(a,13)^rotr(a,22);
        uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        uint32_t t2 = S0 + maj;
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    state[0]+=a; state[1]+=b; state[2]+=c; state[3]+=d;
    state[4]+=e; state[5]+=f; state[6]+=g; state[7]+=h;
}

/* Correct vectorized schedule using the classic 4-word SSE method.
   After computing a candidate that ignores intra-group sig1 dependence,
   we fix up. See: https://github.com/noloader/SHA-Intrinsics and Intel paper.
   Implementation adapted from public-domain sse sha256 (Jeff Walton / noloader style,
   which itself follows Intel).
*/
static inline __m128i s0_epi32(__m128i x) {
    return _mm_xor_si128(
        _mm_xor_si128(_mm_or_si128(_mm_srli_epi32(x, 7), _mm_slli_epi32(x, 25)),
                      _mm_or_si128(_mm_srli_epi32(x, 18), _mm_slli_epi32(x, 14))),
        _mm_srli_epi32(x, 3));
}
static inline __m128i s1_epi32(__m128i x) {
    return _mm_xor_si128(
        _mm_xor_si128(_mm_or_si128(_mm_srli_epi32(x, 17), _mm_slli_epi32(x, 15)),
                      _mm_or_si128(_mm_srli_epi32(x, 19), _mm_slli_epi32(x, 13))),
        _mm_srli_epi32(x, 10));
}

static void sha256_block_vec(uint32_t state[8], const uint8_t block[64]) {
    const __m128i MASK = _mm_set_epi8(12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);
    __m128i W0 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block +  0)), MASK);
    __m128i W1 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block + 16)), MASK);
    __m128i W2 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block + 32)), MASK);
    __m128i W3 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block + 48)), MASK);

