        _mm_or_si128(_mm_srli_epi32(x, 7), _mm_slli_epi32(x, 25)),
        _mm_or_si128(_mm_srli_epi32(x, 18), _mm_slli_epi32(x, 14))),
        _mm_srli_epi32(x, 3));
}
static inline __m128i sigma1(__m128i x) {
    return _mm_xor_si128(_mm_xor_si128(
        _mm_or_si128(_mm_srli_epi32(x, 17), _mm_slli_epi32(x, 15)),
        _mm_or_si128(_mm_srli_epi32(x, 19), _mm_slli_epi32(x, 13))),
        _mm_srli_epi32(x, 10));
}

/* Expand next 4 words given previous 16 held as 4 xmm, using the
   dependency-resolving method from:
   https://www.intel.com/content/www/us/en/developer/articles/technical/intel-sha-extensions.html
   (the pre-SHA-NI SSE schedule). */
static inline __m128i expand(__m128i w0, __m128i w1, __m128i w2, __m128i w3) {
    /* w0 = W[i-16..i-13], w1=W[i-12..i-9], w2=W[i-8..i-5], w3=W[i-4..i-1]
       want W[i..i+3] */
    __m128i t0 = _mm_alignr_epi8(w1, w0, 4);   /* W[i-15 .. i-12] */
    __m128i t1 = sigma0(t0);
    __m128i t2 = _mm_add_epi32(w0, t1);        /* + W[i-16..i-13] */
    __m128i t3 = _mm_alignr_epi8(w3, w2, 4);   /* W[i-7 .. i-4] */
    t2 = _mm_add_epi32(t2, t3);                /* + W[i-7 .. i-4] */
