        if (which==0) sha256_block_opt(st, data+i*64);
        else sha256_block_sse(st, data+i*64);
    }
    uint8_t last[128];
    size_t rem=len%64;
    memcpy(last, data+nb*64, rem);
    last[rem]=0x80;
    size_t pad = rem<56?64:128;
    memset(last+rem+1, 0, pad-rem-1);
    uint64_t bits=(uint64_t)len*8;
    for(int i=0;i<8;i++) last[pad-1-i]=(uint8_t)(bits>>(8*i));
