/* 8-way AVX2 SHA-256. Each ymm lane is an independent message.
   Message schedule and rounds are fully vectorized.
*/
#include <immintrin.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/sha.h>

static const uint32_t K[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

static inline __m256i rotr(__m256i x, int n) {
    return _mm256_or_si256(_mm256_srli_epi32(x, n), _mm256_slli_epi32(x, 32-n));
}
static inline __m256i sig0(__m256i x) {
    return _mm256_xor_si256(_mm256_xor_si256(rotr(x, 7), rotr(x, 18)), _mm256_srli_epi32(x, 3));
}
static inline __m256i sig1(__m256i x) {
    return _mm256_xor_si256(_mm256_xor_si256(rotr(x, 17), rotr(x, 19)), _mm256_srli_epi32(x, 10));
}
static inline __m256i bigS0(__m256i x) {
    return _mm256_xor_si256(_mm256_xor_si256(rotr(x, 2), rotr(x, 13)), rotr(x, 22));
}
static inline __m256i bigS1(__m256i x) {
    return _mm256_xor_si256(_mm256_xor_si256(rotr(x, 6), rotr(x, 11)), rotr(x, 25));
}
static inline __m256i Ch(__m256i e, __m256i f, __m256i g) {
    return _mm256_xor_si256(_mm256_and_si256(e, f), _mm256_andnot_si256(e, g));
}
static inline __m256i Maj(__m256i a, __m256i b, __m256i c) {
    return _mm256_xor_si256(_mm256_xor_si256(_mm256_and_si256(a, b), _mm256_and_si256(a, c)), _mm256_and_si256(b, c));
}

/* Load 8 messages' word i (big-endian) into a ymm. msg[lane] points at 64-byte block. */
static inline __m256i load_word(const uint8_t *msg[8], int word) {
    uint32_t tmp[8];
    for (int lane = 0; lane < 8; lane++) {
        uint32_t v;
        memcpy(&v, msg[lane] + 4*word, 4);
        tmp[lane] = __builtin_bswap32(v);
    }
    return _mm256_loadu_si256((const __m256i*)tmp);
}

static void sha256_8way(const uint8_t *msg[8], uint8_t out[8][32]) {
    __m256i a = _mm256_set1_epi32(0x6a09e667);
    __m256i b = _mm256_set1_epi32(0xbb67ae85);
    __m256i c = _mm256_set1_epi32(0x3c6ef372);
    __m256i d = _mm256_set1_epi32(0xa54ff53a);
    __m256i e = _mm256_set1_epi32(0x510e527f);
    __m256i f = _mm256_set1_epi32(0x9b05688c);
    __m256i g = _mm256_set1_epi32(0x1f83d9ab);
    __m256i h = _mm256_set1_epi32(0x5be0cd19);

    __m256i w[64];
    for (int i = 0; i < 16; i++) w[i] = load_word(msg, i);
    for (int i = 16; i < 64; i++) {
        w[i] = _mm256_add_epi32(_mm256_add_epi32(w[i-16], sig0(w[i-15])),
                                _mm256_add_epi32(w[i-7], sig1(w[i-2])));
    }
    for (int i = 0; i < 64; i++) {
        __m256i t1 = _mm256_add_epi32(h, _mm256_add_epi32(bigS1(e),
                        _mm256_add_epi32(Ch(e, f, g),
                        _mm256_add_epi32(_mm256_set1_epi32(K[i]), w[i]))));
        __m256i t2 = _mm256_add_epi32(bigS0(a), Maj(a, b, c));
        h = g; g = f; f = e;
        e = _mm256_add_epi32(d, t1);
        d = c; c = b; b = a;
        a = _mm256_add_epi32(t1, t2);
    }
    a = _mm256_add_epi32(a, _mm256_set1_epi32(0x6a09e667));
    b = _mm256_add_epi32(b, _mm256_set1_epi32(0xbb67ae85));
    c = _mm256_add_epi32(c, _mm256_set1_epi32(0x3c6ef372));
    d = _mm256_add_epi32(d, _mm256_set1_epi32(0xa54ff53a));
    e = _mm256_add_epi32(e, _mm256_set1_epi32(0x510e527f));
    f = _mm256_add_epi32(f, _mm256_set1_epi32(0x9b05688c));
    g = _mm256_add_epi32(g, _mm256_set1_epi32(0x1f83d9ab));
    h = _mm256_add_epi32(h, _mm256_set1_epi32(0x5be0cd19));

    uint32_t A[8],B[8],C[8],D[8],E[8],F[8],G[8],H[8];
    _mm256_storeu_si256((__m256i*)A, a);
    _mm256_storeu_si256((__m256i*)B, b);
    _mm256_storeu_si256((__m256i*)C, c);
    _mm256_storeu_si256((__m256i*)D, d);
    _mm256_storeu_si256((__m256i*)E, e);
    _mm256_storeu_si256((__m256i*)F, f);
    _mm256_storeu_si256((__m256i*)G, g);
    _mm256_storeu_si256((__m256i*)H, h);
    for (int lane = 0; lane < 8; lane++) {
        uint32_t st[8] = {A[lane],B[lane],C[lane],D[lane],E[lane],F[lane],G[lane],H[lane]};
        for (int i = 0; i < 8; i++) {
            uint32_t v = __builtin_bswap32(st[i]);
            memcpy(out[lane] + 4*i, &v, 4);
        }
    }
}

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec/1e9; }

int main() {
    uint8_t block[64];
    memset(block, 0x61, 64);
    const uint8_t *msg[8];
    for (int i = 0; i < 8; i++) msg[i] = block;
    uint8_t out[8][32];
    sha256_8way(msg, out);
    unsigned char expect[32];
    SHA256(block, 64, expect);
    printf("expect "); for (int i=0;i<32;i++) printf("%02x", expect[i]); printf("\n");
    printf("got    "); for (int i=0;i<32;i++) printf("%02x", out[0][i]); printf("\n");
    printf("match %d\n", memcmp(out[0], expect, 32)==0);

    /* throughput: hash 8 independent 2.5MB messages */
    size_t n = 2560*1024; /* multiple of 64, no padding in this microbench: we only hash full blocks via repeated 1-block? 
       Better: time many 1-block calls vs openssl on same bytes. */
    int blocks = 200000; /* 200000*64 = 12.8MB per lane, 8 lanes = 102.4MB */
    uint8_t *buf = aligned_alloc(64, (size_t)blocks*64);
    memset(buf, 0x5a, (size_t)blocks*64);
    const uint8_t *m[8];
    for (int i = 0; i < 8; i++) m[i] = buf; /* same buffer, independent lanes logically */

    double t0 = now();
    for (int b = 0; b < blocks; b++) {
        for (int i = 0; i < 8; i++) m[i] = buf + (size_t)b*64;
        sha256_8way(m, out);
    }
    double t1 = now();
    double bytes = (double)blocks * 64 * 8;
    printf("8way one-block-at-a-time: %.3f s  %.1f MB/s (includes re-init each block, NOT incremental)\n",
           t1-t0, (bytes/1e6)/(t1-t0));
    return 0;
}
