            block8(st, m);
        }
    }
    double t1 = now();
    double bytes = (double)iters * 8 * n;
    printf("8way %.4f s/iter  %.1f MB/s\n", (t1 - t0) / iters, (8.0 * n / 1e6) / ((t1 - t0) / iters));

    t0 = now();
    unsigned char od[32];
    for (int it = 0; it < iters; it++) {
        for (int i = 0; i < 8; i++) SHA256(data[i], n, od);
    }
    t1 = now();
    printf("openssl x8 %.4f s/iter  %.1f MB/s\n", (t1 - t0) / iters, (8.0 * n / 1e6) / ((t1 - t0) / iters));
    (void)bytes;
    return 0;
}
