/* Hash 8 equal-length messages. out[lane][32]. */
static void sha256_8(const uint8_t *data[8], size_t len, uint8_t out[8][32]) {
    state8 s;
    init8(&s);
    size_t nblocks = len / 64;
    for (size_t b = 0; b < nblocks; b++) {
        const uint8_t *m[8];
        for (int i = 0; i < 8; i++) m[i] = data[i] + b * 64;
        block8(&s, m);
    }
    size_t rem = len % 64;
    uint8_t last[8][128];
    size_t pad = (rem < 56) ? 64 : 128;
    uint64_t bits = (uint64_t)len * 8;
    for (int lane = 0; lane < 8; lane++) {
        memcpy(last[lane], data[lane] + nblocks * 64, rem);
        last[lane][rem] = 0x80;
        memset(last[lane] + rem + 1, 0, pad - rem - 1);
        for (int i = 0; i < 8; i++) last[lane][pad - 1 - i] = (uint8_t)(bits >> (8 * i));
    }
    for (size_t b = 0; b < pad / 64; b++) {
        const uint8_t *m[8];
        for (int i = 0; i < 8; i++) m[i] = last[i] + b * 64;
        block8(&s, m);
