    uint32_t words[8][8];
    for (int i = 0; i < 8; i++) _mm256_storeu_si256((__m256i *)words[i], s.st[i]);
    for (int lane = 0; lane < 8; lane++) {
        for (int i = 0; i < 8; i++) {
            uint32_t v = __builtin_bswap32(words[i][lane]);
            memcpy(out[lane] + 4 * i, &v, 4);
        }
    }
}

static double now(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec / 1e9;
}

int main(void) {
    /* correctness: various lengths */
    size_t lens[] = {0, 1, 55, 56, 63, 64, 65, 100, 128, 1000, 4096, 20000 * 1024};
    int ok = 1;
    for (size_t li = 0; li < sizeof(lens) / sizeof(lens[0]); li++) {
        size_t n = lens[li];
        uint8_t *buf = malloc(n ? n : 1);
        for (size_t i = 0; i < n; i++) buf[i] = (uint8_t)(i * 131u + 7 + li);
        const uint8_t *data[8];
        for (int i = 0; i < 8; i++) data[i] = buf; /* identical, just check lane 0; also vary */
        /* make lanes differ */
        uint8_t *bufs[8];
        for (int i = 0; i < 8; i++) {
            bufs[i] = malloc(n ? n : 1);
            for (size_t j = 0; j < n; j++) bufs[i][j] = (uint8_t)(buf[j] + i);
            data[i] = bufs[i];
