        for (int lane = 0; lane < 8; lane++) {
            unsigned char exp[32];
            SHA256(bufs[lane], n, exp);
            if (memcmp(out[lane], exp, 32) != 0) {
                printf("FAIL len=%zu lane=%d\n", n, lane);
                ok = 0;
            }
        }
        for (int i = 0; i < 8; i++) free(bufs[i]);
        free(buf);
        if (!ok) break;
        printf("ok len=%zu\n", n);
    }
    if (!ok) return 1;

    size_t n = 20000u * 1024u;
    uint8_t *bufs[8];
    const uint8_t *data[8];
    for (int i = 0; i < 8; i++) {
        bufs[i] = malloc(n);
        memset(bufs[i], 0x5a + i, n);
        data[i] = bufs[i];
    }
    uint8_t out[8][32];
    int iters = 3;
    double t0 = now();
    for (int i = 0; i < iters; i++) sha256_8(data, n, out);
    double t1 = now();
    printf("8way full hash %.4f s  %.1f MB/s\n", (t1 - t0) / iters, (8.0 * n / 1e6) / ((t1 - t0) / iters));

    unsigned char od[32];
    t0 = now();
    for (int it = 0; it < iters; it++)
        for (int i = 0; i < 8; i++) SHA256(bufs[i], n, od);
    t1 = now();
    printf("openssl x8 %.4f s  %.1f MB/s\n", (t1 - t0) / iters, (8.0 * n / 1e6) / ((t1 - t0) / iters));
    return 0;
}
